//! Named configurations of the general turbo code of [`crate::turbo`].
//!
//! - The 3GPP2 code as ETSI EN 302 583 (DVB-SH) clause 5.3 uses it: the 8-state constituent with two parities, the interleaver
//!   generated by counter, lookup table and bit reversal (clause 5.3.3, table 5.5 columns n = 6 and n = 9), the twelve puncturing
//!   patterns of table 5.2 and the tail patterns of table 5.3.
//! - The code of ETSI TS 102 744-2-1 clause 5.3.8 (Family SL): the 16-state constituent, encoder 1 flushed by 4 bits inside the
//!   data, encoder 2 open, an interleaver and a transmission map given as tables by the caller (Annex C).

use crate::error::{FecError, Param, Result};
use crate::turbo::{End, Slot, TurboCode, RSC_3GPP2, RSC_SL};

/// The block sizes EN 302 583 uses: 1146 (signalling field) and 12 282 (EFRAME).
pub const SH_BLOCKS: [usize; 2] = [1146, 12_282];

/// Table 5.5 of EN 302 583, the column n = 6.
const SH_LOOKUP_6: [u32; 32] = [
    3, 27, 15, 13, 29, 5, 1, 31, 3, 9, 15, 31, 17, 5, 39, 1, 19, 27, 15, 13, 45, 5, 33, 15, 13, 9,
    15, 31, 17, 5, 15, 33,
];

/// Table 5.5 of EN 302 583, the column n = 9.
const SH_LOOKUP_9: [u32; 32] = [
    13, 335, 87, 15, 15, 1, 333, 11, 13, 1, 121, 155, 1, 175, 421, 5, 509, 215, 47, 425, 295, 229,
    427, 83, 409, 387, 193, 57, 501, 313, 489, 391,
];

/// The interleaver of EN 302 583 clause 5.3.3 for `k` in [`SH_BLOCKS`]: entry `i` is the input bit that encoder 2 reads at
/// step `i`.
pub fn sh_interleaver(k: usize) -> Result<Vec<u32>> {
    let (n, table) = match k {
        1146 => (6u32, &SH_LOOKUP_6),
        12_282 => (9u32, &SH_LOOKUP_9),
        _ => {
            return Err(FecError::NotAllowed {
                param: Param::K,
                got: k as i64,
            })
        }
    };
    let mask = (1u32 << n) - 1;
    let mut out = Vec::with_capacity(k);
    let mut c = 0u32;
    while out.len() < k && c < 1 << (n + 5) {
        let m = ((c >> 5) + 1) & mask;
        let t = table[(c & 31) as usize];
        let l = (m * t) & mask;
        let r = (c & 31).reverse_bits() >> 27;
        let a = (r << n) + l;
        if (a as usize) < k {
            out.push(a);
        }
        c += 1;
    }
    Ok(out)
}

/// A puncturing pattern of EN 302 583: the data periods of table 5.2 and the six tail periods of table 5.3. Each period has six
/// digits for X, Y0, Y1, X', Y'0, Y'1: in data periods 1 sends and 0 deletes; in tail periods the digit is the number of copies.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ShPattern {
    /// The Punct_Pat_ID (0 .. 11).
    pub id: u8,
    /// The code rate as (numerator, denominator).
    pub rate: (u32, u32),
    /// Whether the pattern is the complementary one of its rate.
    pub complementary: bool,
    /// The data periods, repeating.
    pub data: &'static [[u8; 6]],
    /// The tail periods: the first three clock encoder 1, the last three encoder 2.
    pub tail: [[u8; 6]; 6],
}

const fn p(s: &[u8; 6]) -> [u8; 6] {
    [
        s[0] - b'0',
        s[1] - b'0',
        s[2] - b'0',
        s[3] - b'0',
        s[4] - b'0',
        s[5] - b'0',
    ]
}

