/// The pattern of a Punct_Pat_ID, `None` for 12 .. 15 (reserved).
pub fn sh_pattern(id: u8) -> Option<&'static ShPattern> {
    SH_PATTERNS.get(id as usize)
}

/// The 3GPP2 turbo code for block size `k` (1146 or 12 282), both encoders terminated by tail periods.
pub fn sh_code(k: usize) -> Result<TurboCode> {
    TurboCode::new(RSC_3GPP2, k, sh_interleaver(k)?, [End::Tail, End::Tail])
}

/// The transmission map of pattern `pat` for block size `k`: per data period the six outputs X, Y0, Y1, X', Y'0, Y'1 in that order
/// where the pattern sends them; then the six tail periods, each repeated output sent its number of times in a row.
pub fn sh_map(k: usize, pat: &ShPattern) -> Vec<Slot> {
    let mut m = Vec::with_capacity(sh_coded_len(k, pat));
    for t in 0..k {
        let d = &pat.data[t % pat.data.len()];
        for (s, &on) in d.iter().enumerate() {
            if on != 0 {
                m.push(Slot {
                    stream: s as u8,
                    period: t as u32,
                });
            }
        }
    }
    for (j, d) in pat.tail.iter().enumerate() {
        let period = (k + j % 3) as u32;
        for (s, &copies) in d.iter().enumerate() {
            for _ in 0..copies {
                m.push(Slot {
                    stream: s as u8,
                    period,
                });
            }
        }
    }
    m
}

/// The number of coded symbols of pattern `pat` for block size `k` (data and tail periods).
pub fn sh_coded_len(k: usize, pat: &ShPattern) -> usize {
    let per: Vec<usize> = pat
        .data
        .iter()
        .map(|d| d.iter().map(|&x| x as usize).sum())
        .collect();
    let data: usize = (0..k).map(|t| per[t % per.len()]).sum();
    let tail: usize = pat
        .tail
        .iter()
        .flat_map(|d| d.iter())
        .map(|&x| x as usize)
        .sum();
    data + tail
}

/// The Family SL code of TS 102 744-2-1 clause 5.3.8 for an interleaver table `tci` of `N = K + 4` entries (q-bit `i` reads
/// data bit `tci[i]`). The extrinsic scale is 0.72.
pub fn sl_code(tci: &[u32]) -> Result<TurboCode> {
    if tci.len() < 5 {
        return Err(FecError::InputLength {
            expected: 5,
            got: tci.len(),
        });
    }
    Ok(
        TurboCode::new(RSC_SL, tci.len() - 4, tci.to_vec(), [End::Flush, End::Open])?
            .with_scale(18, 25),
    )
}

/// The transmission map of a Family SL symbol-mapping table: raw indices address `d` at `0 .. N`, `p` at `N .. 2N` and `q` at
/// `2N .. 3N` (Annex C.2). An error for an index of `3N` or more.
pub fn sl_map(indices: &[u32], n: usize) -> Result<Vec<Slot>> {
    indices
        .iter()
        .map(|&x| {
            let x = x as usize;
            let (stream, period) = match x / n.max(1) {
                0 => (0u8, x),
                1 => (1, x - n),
                2 => (3, x - 2 * n),
                _ => {
                    return Err(FecError::OutOfRange {
                        param: Param::Table,
                        min: 0,
                        max: 3 * n as i64 - 1,
                        got: x as i64,
                    })
                }
            };
            Ok(Slot {
                stream,
                period: period as u32,
            })
        })
        .collect()
}
